// lib/commands.ts
import {
  Copy,
  CreditCard,
  FolderPlus,
  Home,
  LayoutDashboard,
  Laptop,
  LifeBuoy,
  Moon,
  Settings,
  Sun,
  type LucideIcon,
} from "lucide-react";

export type CommandGroup = "Navigation" | "Actions" | "Theme";

export const GROUP_ORDER: CommandGroup[] = ["Navigation", "Actions", "Theme"];

export type CommandAction =
  | { type: "navigate"; href: string }
  | { type: "theme"; theme: "light" | "dark" | "system" }
  | { type: "copy-url" };

export interface Command {
  id: string;
  label: string;
  group: CommandGroup;
  icon: LucideIcon;
  keywords?: string[];
  action: CommandAction;
}

export const COMMANDS: Command[] = [
  { id: "nav-home", label: "Go to Home", group: "Navigation", icon: Home, keywords: ["landing", "start"], action: { type: "navigate", href: "/" } },
  { id: "nav-dashboard", label: "Go to Dashboard", group: "Navigation", icon: LayoutDashboard, keywords: ["overview", "analytics"], action: { type: "navigate", href: "/dashboard" } },
  { id: "nav-billing", label: "Go to Billing", group: "Navigation", icon: CreditCard, keywords: ["invoice", "payment", "plan"], action: { type: "navigate", href: "/billing" } },
  { id: "nav-settings", label: "Go to Settings", group: "Navigation", icon: Settings, keywords: ["preferences", "account"], action: { type: "navigate", href: "/settings" } },
  { id: "act-new-project", label: "Create new project", group: "Actions", icon: FolderPlus, keywords: ["add", "new"], action: { type: "navigate", href: "/projects/new" } },
  { id: "act-copy-url", label: "Copy page link", group: "Actions", icon: Copy, keywords: ["share", "url"], action: { type: "copy-url" } },
  { id: "act-support", label: "Contact support", group: "Actions", icon: LifeBuoy, keywords: ["help", "chat"], action: { type: "navigate", href: "/support" } },
  { id: "theme-light", label: "Switch to light theme", group: "Theme", icon: Sun, keywords: ["appearance", "bright"], action: { type: "theme", theme: "light" } },
  { id: "theme-dark", label: "Switch to dark theme", group: "Theme", icon: Moon, keywords: ["appearance", "night"], action: { type: "theme", theme: "dark" } },
  { id: "theme-system", label: "Use system theme", group: "Theme", icon: Laptop, keywords: ["appearance", "auto"], action: { type: "theme", theme: "system" } },
];

// lib/command-search.ts
import type { Command } from "@/lib/commands";

function isSubsequence(needle: string, haystack: string): boolean {
  let cursor = 0;
  for (let i = 0; i < haystack.length && cursor < needle.length; i++) {
    if (haystack[i] === needle[cursor]) cursor++;
  }
  return cursor === needle.length;
}

function scoreCommand(command: Command, query: string): number {
  const label = command.label.toLowerCase();
  if (label.startsWith(query)) return 100;
  if (label.split(" ").some((word) => word.startsWith(query))) return 80;
  if (label.includes(query)) return 60;
  if (command.keywords?.some((keyword) => keyword.toLowerCase().includes(query))) return 40;
  if (isSubsequence(query, label)) return 20;
  return 0;
}

export function searchCommands(commands: Command[], rawQuery: string): Command[] {
  const query = rawQuery.trim().toLowerCase();
  if (!query) return commands;

  return commands
    .map((command, order) => ({ command, order, score: scoreCommand(command, query) }))
    .filter((entry) => entry.score > 0)
    .sort((a, b) => b.score - a.score || a.order - b.order)
    .map((entry) => entry.command);
}

export interface Segment {
  text: string;
  match: boolean;
}

export function highlightSegments(text: string, rawQuery: string): Segment[] {
  const query = rawQuery.trim().toLowerCase();
  const start = query ? text.toLowerCase().indexOf(query) : -1;
  if (start === -1) return [{ text, match: false }];

  const end = start + query.length;
  return [
    { text: text.slice(0, start), match: false },
    { text: text.slice(start, end), match: true },
    { text: text.slice(end), match: false },
  ].filter((segment) => segment.text.length > 0);
}

// components/command-palette.tsx  (npm i framer-motion lucide-react)
"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { useRouter } from "next/navigation";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { CornerDownLeft, Search } from "lucide-react";
import { COMMANDS, GROUP_ORDER, type Command } from "@/lib/commands";
import { highlightSegments, searchCommands } from "@/lib/command-search";

interface CommandPaletteContextValue {
  isOpen: boolean;
  open: () => void;
  close: () => void;
  toggle: () => void;
}

const CommandPaletteContext = createContext<CommandPaletteContextValue | null>(null);

export function useCommandPalette(): CommandPaletteContextValue {
  const context = useContext(CommandPaletteContext);
  if (!context) {
    throw new Error("useCommandPalette must be used inside <CommandPaletteProvider>.");
  }
  return context;
}

// Requires Tailwind darkMode: "class" (or the equivalent custom variant in Tailwind v4).
function applyTheme(theme: "light" | "dark" | "system") {
  const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
  document.documentElement.classList.toggle("dark", theme === "dark" || (theme === "system" && prefersDark));
  try {
    window.localStorage.setItem("theme", theme);
  } catch {
    // Storage can be unavailable (private mode); the theme still applies for this session.
  }
}

export function CommandPaletteProvider({ children }: { children: ReactNode }) {
  const [isOpen, setIsOpen] = useState(false);

  const open = useCallback(() => setIsOpen(true), []);
  const close = useCallback(() => setIsOpen(false), []);
  const toggle = useCallback(() => setIsOpen((previous) => !previous), []);

  useEffect(() => {
    function onKeyDown(event: globalThis.KeyboardEvent) {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setIsOpen((previous) => !previous);
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  const value = useMemo(() => ({ isOpen, open, close, toggle }), [isOpen, open, close, toggle]);

  return (
    <CommandPaletteContext.Provider value={value}>
      {children}
      <AnimatePresence>{isOpen && <PaletteContent onClose={close} />}</AnimatePresence>
    </CommandPaletteContext.Provider>
  );
}

// Mounted only while open, so query and cursor state reset automatically on every open.
function PaletteContent({ onClose }: { onClose: () => void }) {
  const router = useRouter();
  const reduceMotion = useReducedMotion();
  const listboxId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);

  const groups = useMemo(() => {
    const results = searchCommands(COMMANDS, query);
    return GROUP_ORDER.map((group) => ({
      group,
      items: results.filter((command) => command.group === group),
    })).filter((entry) => entry.items.length > 0);
  }, [query]);

  // Keyboard order must match the visual (grouped) order.
  const flat = useMemo(() => groups.flatMap((entry) => entry.items), [groups]);
  const activeCommand: Command | undefined = flat[activeIndex];

  useEffect(() => {
    const previouslyFocused = document.activeElement as HTMLElement | null;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    inputRef.current?.focus();

    return () => {
      document.body.style.overflow = previousOverflow;
      previouslyFocused?.focus?.();
    };
  }, []);

  useEffect(() => {
    if (!activeCommand) return;
    document.getElementById(`${listboxId}-${activeCommand.id}`)?.scrollIntoView({ block: "nearest" });
  }, [activeCommand, listboxId]);

  const run = useCallback(
    (command: Command) => {
      onClose();
      const { action } = command;
      switch (action.type) {
        case "navigate":
          router.push(action.href);
          break;
        case "theme":
          applyTheme(action.theme);
          break;
        case "copy-url":
          void navigator.clipboard?.writeText(window.location.href).catch(() => undefined);
          break;
      }
    },
    [onClose, router]
  );

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.nativeEvent.isComposing) return;

    switch (event.key) {
      case "ArrowDown":
        event.preventDefault();
        if (flat.length > 0) setActiveIndex((index) => (index + 1) % flat.length);
        break;
      case "ArrowUp":
        event.preventDefault();
        if (flat.length > 0) setActiveIndex((index) => (index - 1 + flat.length) % flat.length);
        break;
      case "Enter":
        event.preventDefault();
        if (activeCommand) run(activeCommand);
        break;
      case "Escape":
        event.preventDefault();
        onClose();
        break;
      case "Tab":
        // The input is the only focus target inside the dialog.
        event.preventDefault();
        break;
    }
  }

  const duration = reduceMotion ? 0 : 0.18;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center px-4 pt-[12vh] sm:pt-[16vh]">
      <motion.div
        aria-hidden
        className="absolute inset-0 bg-slate-950/60 backdrop-blur-sm"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        transition={{ duration }}
        onClick={onClose}
      />

      <motion.div
        role="dialog"
        aria-modal="true"
        aria-label="Command palette"
        onKeyDown={handleKeyDown}
        initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.96, y: reduceMotion ? 0 : -8 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.98, y: reduceMotion ? 0 : -4 }}
        transition={{ duration, ease: "easeOut" }}
        className="relative w-full max-w-xl overflow-hidden rounded-2xl border border-white/20 bg-white/80 shadow-2xl shadow-slate-950/30 ring-1 ring-black/5 backdrop-blur-2xl dark:border-white/10 dark:bg-slate-900/80"
      >
        <div className="flex items-center gap-3 border-b border-slate-200/70 px-4 dark:border-white/10">
          <Search className="h-5 w-5 shrink-0 text-slate-400" aria-hidden />
          <input
            ref={inputRef}
            type="text"
            role="combobox"
            aria-label="Search commands"
            aria-autocomplete="list"
            aria-expanded={flat.length > 0}
            aria-controls={flat.length > 0 ? listboxId : undefined}
            aria-activedescendant={activeCommand ? `${listboxId}-${activeCommand.id}` : undefined}
            autoComplete="off"
            autoCorrect="off"
            spellCheck={false}
            placeholder="Type a command or search..."
            value={query}
            onChange={(event) => {
              setQuery(event.target.value);
              setActiveIndex(0);
            }}
            className="h-14 w-full bg-transparent text-base text-slate-900 outline-none placeholder:text-slate-400 dark:text-white"
          />
          <kbd className="hidden rounded-md border border-slate-200 px-1.5 py-0.5 text-[10px] font-medium text-slate-500 sm:block dark:border-white/10 dark:text-slate-400">
            ESC
          </kbd>
        </div>

        {flat.length === 0 ? (
          <p role="status" className="px-4 py-14 text-center text-sm text-slate-500 dark:text-slate-400">
            No results for &ldquo;{query}&rdquo;
          </p>
        ) : (
          <div id={listboxId} role="listbox" aria-label="Commands" className="max-h-80 overflow-y-auto overscroll-contain p-2">
            {groups.map(({ group, items }) => (
              <div key={group} role="group" aria-labelledby={`${listboxId}-group-${group}`} className="mb-1 last:mb-0">
                <p
                  id={`${listboxId}-group-${group}`}
                  className="px-3 pb-1 pt-2 text-xs font-semibold uppercase tracking-wider text-slate-400"
                >
                  {group}
                </p>

                {items.map((command) => {
                  const index = flat.indexOf(command);
                  const isActive = index === activeIndex;
                  const Icon = command.icon;

                  return (
                    <div
                      key={command.id}
                      id={`${listboxId}-${command.id}`}
                      role="option"
                      aria-selected={isActive}
                      // onMouseMove (not onMouseEnter) so keyboard scrolling under a still cursor never steals the selection.
                      onMouseMove={() => {
                        if (index !== activeIndex) setActiveIndex(index);
                      }}
                      onClick={() => run(command)}
                      className={`flex cursor-pointer items-center gap-3 rounded-xl px-3 py-2.5 text-sm transition-colors ${
                        isActive
                          ? "bg-indigo-500 text-white shadow-lg shadow-indigo-500/25"
                          : "text-slate-700 dark:text-slate-200"
                      }`}
                    >
                      <Icon className={`h-4 w-4 shrink-0 ${isActive ? "text-white" : "text-slate-400"}`} aria-hidden />
                      <span className="flex-1 truncate">
                        {highlightSegments(command.label, query).map((segment, segmentIndex) =>
                          segment.match ? (
                            <mark
                              key={segmentIndex}
                              className={`bg-transparent font-semibold ${
                                isActive
                                  ? "text-white underline decoration-white/60 underline-offset-2"
                                  : "text-indigo-600 dark:text-indigo-400"
                              }`}
                            >
                              {segment.text}
                            </mark>
                          ) : (
                            <span key={segmentIndex}>{segment.text}</span>
                          )
                        )}
                      </span>
                      {isActive && <CornerDownLeft className="h-3.5 w-3.5 text-white/80" aria-hidden />}
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        )}

        <div className="flex items-center justify-between border-t border-slate-200/70 px-4 py-2.5 text-xs text-slate-500 dark:border-white/10 dark:text-slate-400">
          <span className="flex items-center gap-2" aria-hidden>
            <kbd className="rounded border border-slate-200 px-1.5 py-0.5 dark:border-white/10">&uarr;</kbd>
            <kbd className="rounded border border-slate-200 px-1.5 py-0.5 dark:border-white/10">&darr;</kbd>
            navigate
            <kbd className="rounded border border-slate-200 px-1.5 py-0.5 dark:border-white/10">Enter</kbd>
            select
          </span>
          <span aria-live="polite">
            {flat.length} result{flat.length === 1 ? "" : "s"}
          </span>
        </div>
      </motion.div>
    </div>
  );
}

