// lib/pricing.ts
export type BillingCycle = "monthly" | "yearly";
export type PlanId = "starter" | "team" | "scale";

export interface Plan {
  id: PlanId;
  name: string;
  tagline: string;
  seatPrice: number;
  includedRequests: number;
  /** Price per 1,000 requests beyond the included allowance. */
  overagePer1k: number;
  maxSeats: number;
}

export const YEARLY_DISCOUNT = 0.2;
export const MIN_SEATS = 1;
export const MAX_SEATS = 100;

export const REQUEST_STEPS = [
  10_000, 100_000, 500_000, 1_000_000, 5_000_000, 10_000_000, 50_000_000, 100_000_000,
] as const;

export const PLANS: readonly Plan[] = [
  { id: "starter", name: "Starter", tagline: "Solo builders and prototypes", seatPrice: 9, includedRequests: 100_000, overagePer1k: 0.4, maxSeats: 5 },
  { id: "team", name: "Team", tagline: "Growing product teams", seatPrice: 24, includedRequests: 2_000_000, overagePer1k: 0.2, maxSeats: 50 },
  { id: "scale", name: "Scale", tagline: "High-volume production workloads", seatPrice: 39, includedRequests: 20_000_000, overagePer1k: 0.08, maxSeats: MAX_SEATS },
];

export interface Quote {
  seatsCost: number;
  overageRequests: number;
  usageCost: number;
  subtotal: number;
  discount: number;
  /** Monthly-equivalent total after any yearly discount. */
  total: number;
}

const round2 = (value: number) => Math.round(value * 100) / 100;

export function isEligible(plan: Plan, seats: number): boolean {
  return seats <= plan.maxSeats;
}

export function getQuote(plan: Plan, seats: number, requests: number, billing: BillingCycle): Quote {
  const seatsCost = seats * plan.seatPrice;
  const overageRequests = Math.max(0, requests - plan.includedRequests);
  const usageCost = round2(Math.ceil(overageRequests / 1000) * plan.overagePer1k);
  const subtotal = round2(seatsCost + usageCost);
  const discount = billing === "yearly" ? round2(subtotal * YEARLY_DISCOUNT) : 0;

  return { seatsCost, overageRequests, usageCost, subtotal, discount, total: round2(subtotal - discount) };
}

/** Cheapest eligible plan for the given workload. Ties resolve to the lower tier. */
export function recommendPlan(seats: number, requests: number): Plan {
  const eligible = PLANS.filter((plan) => isEligible(plan, seats));
  const pool = eligible.length > 0 ? eligible : [PLANS[PLANS.length - 1]];

  return pool.reduce((best, plan) =>
    getQuote(plan, seats, requests, "monthly").total < getQuote(best, seats, requests, "monthly").total ? plan : best
  );
}

const wholeCurrency = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });
const preciseCurrency = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2 });
const compactNumber = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });

export const formatCurrency = (value: number) => wholeCurrency.format(value);
export const formatPrecise = (value: number) => preciseCurrency.format(value);
export const formatCompact = (value: number) => compactNumber.format(value);

