          {display}
        </output>
      </div>

      <input
        id={id}
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(event) => onChange(Number(event.target.value))}
        aria-valuetext={valueText}
        aria-describedby={hint ? `${id}-hint` : undefined}
        style={{
          background: `linear-gradient(to right, #818cf8 ${percent}%, rgba(255,255,255,0.12) ${percent}%)`,
