  );
}

// components/pricing/animated-price.tsx  (npm i framer-motion)
"use client";

import { useEffect } from "react";
import { motion, useReducedMotion, useSpring, useTransform } from "framer-motion";
import { formatCurrency } from "@/lib/pricing";

interface AnimatedPriceProps {
  value: number;
  className?: string;
}

export default function AnimatedPrice({ value, className }: AnimatedPriceProps) {
  const reduceMotion = useReducedMotion();
  const spring = useSpring(value, { stiffness: 140, damping: 24, mass: 0.6 });
  const label = useTransform(spring, (latest) => formatCurrency(Math.round(latest)));

  useEffect(() => {
    spring.set(value);
  }, [spring, value]);

  if (reduceMotion) {
    return <span className={className}>{formatCurrency(Math.round(value))}</span>;
  }

  return <motion.span className={className}>{label}</motion.span>;
}

