// lib/revenue.ts
export type RangeKey = "7d" | "30d" | "90d";

export interface RevenuePoint {
  /** ISO date (YYYY-MM-DD), always UTC. */
  date: string;
  value: number;
}

export interface RevenueRange {
  key: RangeKey;
  label: string;
  points: RevenuePoint[];
  /** Total for the equally long period immediately before this range. */
  previousTotal: number;
}

const DAY_MS = 86_400_000;
const TOTAL_DAYS = 180;

// Small deterministic PRNG so mock data is stable across renders.
function mulberry32(seed: number) {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

function buildSeries(): RevenuePoint[] {
  const random = mulberry32(2024);
  const now = new Date();
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());

  return Array.from({ length: TOTAL_DAYS }, (_, index) => {
    const trend = 3200 + index * 18;
    const weekly = Math.sin((index / 7) * Math.PI * 2) * 420;
    const noise = (random() - 0.5) * 700;

    return {
      date: new Date(today - (TOTAL_DAYS - 1 - index) * DAY_MS).toISOString().slice(0, 10),
      value: Math.max(500, Math.round(trend + weekly + noise)),
    };
  });
}

const RANGES: { key: RangeKey; label: string; days: number }[] = [
  { key: "7d", label: "7D", days: 7 },
  { key: "30d", label: "30D", days: 30 },
  { key: "90d", label: "90D", days: 90 },
];

export async function getRevenueRanges(): Promise<RevenueRange[]> {
  // Replace with a real database or analytics API call.
  const series = buildSeries();
  const sum = (points: RevenuePoint[]) => points.reduce((total, point) => total + point.value, 0);

  return RANGES.map(({ key, label, days }) => ({
    key,
    label,
    points: series.slice(-days),
    previousTotal: sum(series.slice(-days * 2, -days)),
  }));
}

// lib/chart.ts
export const CHART_WIDTH = 600;
export const CHART_HEIGHT = 240;

export interface ChartPoint {
  x: number;
  y: number;
}

export interface ChartGeometry {
  points: ChartPoint[];
  line: string;
  area: string;
  domainMin: number;
  domainMax: number;
}

/** Builds smooth SVG paths (Catmull-Rom converted to cubic Beziers) in a fixed viewBox coordinate space. */
export function buildChart(values: number[]): ChartGeometry | null {
  if (values.length < 2) return null;

  const min = Math.min(...values);
  const max = Math.max(...values);
  const spread = max - min || 1;
  const domainMin = Math.max(0, min - spread * 0.2);
  const domainMax = max + spread * 0.15;
  const step = CHART_WIDTH / (values.length - 1);

  const points: ChartPoint[] = values.map((value, index) => ({
    x: index * step,
    y: (1 - (value - domainMin) / (domainMax - domainMin)) * CHART_HEIGHT,
  }));

  let line = `M${points[0].x.toFixed(2)},${points[0].y.toFixed(2)}`;
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i - 1] ?? points[i];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2] ?? p2;

    const c1x = p1.x + (p2.x - p0.x) / 6;
    const c1y = p1.y + (p2.y - p0.y) / 6;
    const c2x = p2.x - (p3.x - p1.x) / 6;
    const c2y = p2.y - (p3.y - p1.y) / 6;

    line += ` C${c1x.toFixed(2)},${c1y.toFixed(2)} ${c2x.toFixed(2)},${c2y.toFixed(2)} ${p2.x.toFixed(2)},${p2.y.toFixed(2)}`;
  }

  return {
    points,
    line,
    area: `${line} L${CHART_WIDTH},${CHART_HEIGHT} L0,${CHART_HEIGHT} Z`,
    domainMin,
    domainMax,
  };
}

const currency = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });
const compactCurrency = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  notation: "compact",
  maximumFractionDigits: 1,
});
const shortDate = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });

export const formatCurrency = (value: number) => currency.format(value);
export const formatCompactCurrency = (value: number) => compactCurrency.format(value);
export const formatShortDate = (isoDate: string) => shortDate.format(new Date(`${isoDate}T00:00:00Z`));

// components/revenue-chart.tsx  (npm i framer-motion)
"use client";

import { useId, useMemo, type KeyboardEvent, type PointerEvent } from "react";
import { motion, useReducedMotion } from "framer-motion";
import {
  CHART_HEIGHT,
  CHART_WIDTH,
  buildChart,
  formatCompactCurrency,
  formatCurrency,
  formatShortDate,
} from "@/lib/chart";
import type { RevenuePoint } from "@/lib/revenue";

interface RevenueChartProps {
  points: RevenuePoint[];
  label: string;
  activeIndex: number | null;
  onActiveIndexChange: (index: number | null) => void;
}

const GRID_FRACTIONS = [0.05, 0.35, 0.65, 0.95];

export default function RevenueChart({ points, label, activeIndex, onActiveIndexChange }: RevenueChartProps) {
  const reduceMotion = useReducedMotion();
  const gradientId = `rev-${useId().replace(/:/g, "")}`;
  const chart = useMemo(() => buildChart(points.map((point) => point.value)), [points]);

  if (!chart) {
    return (
      <div className="flex h-64 items-center justify-center rounded-xl border border-dashed border-slate-300 text-sm text-slate-500 dark:border-slate-700 dark:text-slate-400">
        Not enough data for this range yet.
      </div>
    );
  }

  const lastIndex = points.length - 1;
  const shown = points[activeIndex ?? lastIndex];
  const active = activeIndex !== null ? points[activeIndex] : null;
  const activePoint = activeIndex !== null ? chart.points[activeIndex] : null;
  const activeFraction = activeIndex !== null ? activeIndex / lastIndex : 0;
  const tooltipAlign =
    activeFraction < 0.15 ? "" : activeFraction > 0.85 ? "-translate-x-full" : "-translate-x-1/2";

  function indexFromPointer(event: PointerEvent<HTMLDivElement>) {
    const rect = event.currentTarget.getBoundingClientRect();
    const ratio = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
    return Math.round(ratio * lastIndex);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const current = activeIndex ?? lastIndex;
    let next: number;

    switch (event.key) {
      case "ArrowLeft":
        next = Math.max(0, current - 1);
        break;
      case "ArrowRight":
        next = Math.min(lastIndex, current + 1);
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = lastIndex;
        break;
      case "Escape":
        onActiveIndexChange(null);
        return;
      default:
        return;
    }

    event.preventDefault();
    onActiveIndexChange(next);
  }

  return (
    <div>
      <div
        role="slider"
        tabIndex={0}
        aria-label={`${label} revenue by day`}
        aria-orientation="horizontal"
        aria-valuemin={0}
        aria-valuemax={lastIndex}
        aria-valuenow={activeIndex ?? lastIndex}
        aria-valuetext={`${formatShortDate(shown.date)}: ${formatCurrency(shown.value)}`}
        onKeyDown={handleKeyDown}
        onPointerMove={(event) => onActiveIndexChange(indexFromPointer(event))}
        onPointerDown={(event) => onActiveIndexChange(indexFromPointer(event))}
        onPointerLeave={() => onActiveIndexChange(null)}
        onBlur={() => onActiveIndexChange(null)}
        className="relative h-64 w-full cursor-crosshair touch-pan-y select-none rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-indigo-400"
      >
        {GRID_FRACTIONS.map((fraction) => (
          <div
            key={fraction}
            aria-hidden
            className="pointer-events-none absolute inset-x-0 border-t border-dashed border-slate-200 dark:border-white/10"
            style={{ top: `${fraction * 100}%` }}
          >
            <span className="absolute -top-2.5 left-0 rounded bg-white/70 px-1 text-[10px] tabular-nums text-slate-400 backdrop-blur-sm dark:bg-slate-900/70">
              {formatCompactCurrency(chart.domainMax - fraction * (chart.domainMax - chart.domainMin))}
            </span>
          </div>
        ))}

        <motion.div
          key={`${points[0].date}-${points.length}`}
          className="absolute inset-0"
          initial={reduceMotion ? false : { clipPath: "inset(0 100% 0 0)" }}
          animate={{ clipPath: "inset(0 0% 0 0)" }}
          transition={{ duration: 0.8, ease: "easeOut" }}
        >
          <svg
            viewBox={`0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`}
            preserveAspectRatio="none"
            aria-hidden
            className="h-full w-full overflow-visible"
          >
            <defs>
              <linearGradient id={`${gradientId}-fill`} x1="0" x2="0" y1="0" y2="1">
                <stop offset="0%" stopColor="#6366f1" stopOpacity="0.35" />
                <stop offset="100%" stopColor="#6366f1" stopOpacity="0" />
              </linearGradient>
              <linearGradient id={`${gradientId}-stroke`} x1="0" x2="1" y1="0" y2="0">
                <stop offset="0%" stopColor="#818cf8" />
                <stop offset="100%" stopColor="#22d3ee" />
              </linearGradient>
            </defs>
            <path d={chart.area} fill={`url(#${gradientId}-fill)`} />
            <path
              d={chart.line}
              fill="none"
              stroke={`url(#${gradientId}-stroke)`}
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              vectorEffect="non-scaling-stroke"
            />
          </svg>
        </motion.div>

        {active && activePoint && (
          <>
            <div
              aria-hidden
              className="pointer-events-none absolute inset-y-0 w-px bg-gradient-to-b from-indigo-400/0 via-indigo-400/60 to-indigo-400/0"
              style={{ left: `${activeFraction * 100}%` }}
            />
            <div
              aria-hidden
              className="pointer-events-none absolute h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white bg-indigo-500 shadow-lg shadow-indigo-500/50"
              style={{ left: `${activeFraction * 100}%`, top: `${(activePoint.y / CHART_HEIGHT) * 100}%` }}
            />
            <div
              aria-hidden
              className={`pointer-events-none absolute top-0 z-10 whitespace-nowrap rounded-lg border border-slate-200 bg-white/90 px-3 py-2 text-xs shadow-xl backdrop-blur dark:border-white/10 dark:bg-slate-900/90 ${tooltipAlign}`}
              style={{ left: `${activeFraction * 100}%` }}
            >
              <p className="text-slate-500 dark:text-slate-400">{formatShortDate(active.date)}</p>
              <p className="mt-0.5 text-sm font-semibold tabular-nums text-slate-900 dark:text-white">
                {formatCurrency(active.value)}
              </p>
            </div>
          </>
        )}
      </div>

      <div aria-hidden className="mt-3 flex justify-between text-xs text-slate-400">
        <span>{formatShortDate(points[0].date)}</span>
        <span>{formatShortDate(points[Math.floor(lastIndex / 2)].date)}</span>
        <span>{formatShortDate(points[lastIndex].date)}</span>
      </div>
    </div>
  );
}

// components/revenue-card.tsx  (npm i lucide-react)
"use client";

import { useId, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { motion } from "framer-motion";
import { ArrowDownRight, ArrowUpRight } from "lucide-react";
import RevenueChart from "@/components/revenue-chart";
import { formatCurrency, formatShortDate } from "@/lib/chart";
import type { RangeKey, RevenueRange } from "@/lib/revenue";

export default function RevenueCard({ ranges }: { ranges: RevenueRange[] }) {
  const baseId = useId();
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const [rangeKey, setRangeKey] = useState<RangeKey | undefined>(() => (ranges.find((item) => item.key === "30d") ?? ranges[0])?.key);
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const range = ranges.find((item) => item.key === rangeKey) ?? ranges[0];

  const stats = useMemo(() => {
    if (!range || range.points.length === 0) return null;

    const total = range.points.reduce((sum, point) => sum + point.value, 0);
    const peak = range.points.reduce((best, point) => (point.value > best.value ? point : best));
    const low = range.points.reduce((best, point) => (point.value < best.value ? point : best));
    const change = range.previousTotal > 0 ? ((total - range.previousTotal) / range.previousTotal) * 100 : 0;

    return { total, average: total / range.points.length, peak, low, change };
  }, [range]);

  if (!range || !stats) {
    return (
      <p className="rounded-2xl border border-dashed border-slate-300 p-10 text-center text-sm text-slate-500 dark:border-slate-700 dark:text-slate-400">
        No revenue data available yet.
      </p>
    );
  }

  function selectRange(key: RangeKey) {
    setRangeKey(key);
    setActiveIndex(null);
  }

  function handleTabKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let next: number;
    if (event.key === "ArrowRight") next = (index + 1) % ranges.length;
    else if (event.key === "ArrowLeft") next = (index - 1 + ranges.length) % ranges.length;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = ranges.length - 1;
    else return;

    event.preventDefault();
    selectRange(ranges[next].key);
    tabRefs.current[next]?.focus();
  }

  const description = `Last ${range.points.length} days`;
  const hovered = activeIndex !== null ? range.points[activeIndex] : null;
  const isUp = stats.change >= 0;
  const DeltaIcon = isUp ? ArrowUpRight : ArrowDownRight;

  return (
    <section
      aria-label="Revenue overview"
      className="w-full max-w-3xl rounded-3xl border border-slate-200 bg-white/80 p-6 shadow-xl shadow-slate-900/5 backdrop-blur-xl dark:border-white/10 dark:bg-slate-900/60 sm:p-8"
    >
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <p className="text-sm font-medium text-slate-500 dark:text-slate-400">
            {hovered ? formatShortDate(hovered.date) : `Total revenue \u00b7 ${description}`}
          </p>
          <p className="mt-2 flex flex-wrap items-center gap-3">
            <span className="text-4xl font-bold tabular-nums tracking-tight text-slate-900 dark:text-white">
              {formatCurrency(hovered ? hovered.value : stats.total)}
            </span>
            <span
              className={`inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 text-xs font-semibold ring-1 ring-inset ${
                isUp
                  ? "bg-emerald-50 text-emerald-700 ring-emerald-600/20 dark:bg-emerald-500/10 dark:text-emerald-400 dark:ring-emerald-400/20"
                  : "bg-rose-50 text-rose-700 ring-rose-600/20 dark:bg-rose-500/10 dark:text-rose-400 dark:ring-rose-400/20"
              }`}
            >
              <DeltaIcon className="h-3 w-3" aria-hidden />
              {Math.abs(stats.change).toFixed(1)}%
              <span className="sr-only"> {isUp ? "increase" : "decrease"} compared to the previous period</span>
            </span>
          </p>
        </div>

        <div role="tablist" aria-label="Date range" className="inline-flex rounded-xl bg-slate-100 p-1 dark:bg-white/5">
          {ranges.map((item, index) => {
            const selected = item.key === range.key;

            return (
              <button
                key={item.key}
                ref={(node) => {
                  tabRefs.current[index] = node;
                }}
                id={`${baseId}-tab-${item.key}`}
                type="button"
                role="tab"
                aria-selected={selected}
                aria-controls={`${baseId}-panel`}
                tabIndex={selected ? 0 : -1}
                onClick={() => selectRange(item.key)}
                onKeyDown={(event) => handleTabKeyDown(event, index)}
                className="relative rounded-lg px-3.5 py-1.5 text-xs font-semibold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500"
              >
                {selected && (
                  <motion.span
                    layoutId={`${baseId}-pill`}
                    transition={{ type: "spring", stiffness: 400, damping: 32 }}
                    className="absolute inset-0 rounded-lg bg-white shadow-sm dark:bg-white/10"
                  />
                )}
                <span
                  className={`relative transition-colors ${
                    selected
                      ? "text-slate-900 dark:text-white"
                      : "text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-white"
                  }`}
                >
                  {item.label}
                </span>
              </button>
            );
          })}
        </div>
      </div>

      <div id={`${baseId}-panel`} role="tabpanel" aria-labelledby={`${baseId}-tab-${range.key}`} className="mt-8">
        <RevenueChart
          points={range.points}
          label={description}
          activeIndex={activeIndex}
          onActiveIndexChange={setActiveIndex}
        />
      </div>

      <dl className="mt-8 grid grid-cols-3 gap-4 border-t border-slate-200 pt-6 dark:border-white/10">
        <div>
          <dt className="text-xs text-slate-500 dark:text-slate-400">Average / day</dt>
          <dd className="mt-1 text-sm font-semibold tabular-nums text-slate-900 dark:text-white">
            {formatCurrency(stats.average)}
          </dd>
        </div>
        <div>
          <dt className="text-xs text-slate-500 dark:text-slate-400">Best day</dt>
          <dd className="mt-1 text-sm font-semibold tabular-nums text-slate-900 dark:text-white">
            {formatCurrency(stats.peak.value)}
            <span className="ml-1.5 text-xs font-normal text-slate-400">{formatShortDate(stats.peak.date)}</span>
          </dd>
        </div>
        <div>
          <dt className="text-xs text-slate-500 dark:text-slate-400">Lowest day</dt>
          <dd className="mt-1 text-sm font-semibold tabular-nums text-slate-900 dark:text-white">
            {formatCurrency(stats.low.value)}
            <span className="ml-1.5 text-xs font-normal text-slate-400">{formatShortDate(stats.low.date)}</span>
          </dd>
        </div>
      </dl>
    </section>
  );
}

